def main():
    import sys
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        return
    m = int(lines[0].split()[0])
    counter = Counter()
    out = []
    for line in lines[1:1 + m]:
        cmd = line.split()[0]
        if cmd == "INC":
            counter.inc()
        elif cmd == "DEC":
            counter.dec()
        elif cmd == "SHOW":
            out.append(str(counter.show()))
    sys.stdout.write("\n".join(out))


